public class DotPaletteCanvasTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static int maskFor(int button) {
        if (button == java.awt.event.MouseEvent.BUTTON1) {
            return java.awt.event.MouseEvent.BUTTON1_DOWN_MASK;
        }
        if (button == java.awt.event.MouseEvent.BUTTON2) {
            return java.awt.event.MouseEvent.BUTTON2_DOWN_MASK;
        }
        return java.awt.event.MouseEvent.BUTTON3_DOWN_MASK;
    }

    static void press(DotPaletteCanvas panel, int button, int x, int y) {
        panel.dispatchEvent(new java.awt.event.MouseEvent(panel,
                java.awt.event.MouseEvent.MOUSE_PRESSED, System.currentTimeMillis(),
                maskFor(button), x, y, 1, false, button));
    }

    public static void main(String[] args) {
        try {
            DotPaletteCanvas panel = new DotPaletteCanvas();
            java.awt.Component label = find(panel, "dots");

            check("no dots at the start", 0, panel.dotCount());
            check("lastDot on an empty canvas", "none", panel.lastDot());

            press(panel, java.awt.event.MouseEvent.BUTTON1, 3, 4);
            press(panel, java.awt.event.MouseEvent.BUTTON1, 9, 9);
            check("left presses add dots", 2, panel.dotCount());
            check("lastDot is the newest", "9,9", panel.lastDot());
            check("label after two dots", "2 dot(s)", textOf(label));

            press(panel, java.awt.event.MouseEvent.BUTTON3, 50, 50);
            check("a right press undoes the newest dot", 1, panel.dotCount());
            check("lastDot after the undo", "3,4", panel.lastDot());

            press(panel, java.awt.event.MouseEvent.BUTTON3, 50, 50);
            press(panel, java.awt.event.MouseEvent.BUTTON3, 50, 50);
            check("undoing an empty canvas is harmless", 0, panel.dotCount());
            check("label back to zero", "0 dot(s)", textOf(label));

            press(panel, java.awt.event.MouseEvent.BUTTON1, 1, 1);
            press(panel, java.awt.event.MouseEvent.BUTTON1, 2, 2);
            press(panel, java.awt.event.MouseEvent.BUTTON2, 7, 7);
            check("a middle press clears everything", "0 none",
                    panel.dotCount() + " " + panel.lastDot());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

