import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class DotPaletteCanvas extends JPanel {

    private final JLabel dotsLabel = new JLabel("0 dot(s)");
    private final List<Point> dots = new ArrayList<>();

    public DotPaletteCanvas() {
        dotsLabel.setName("dots");
        add(dotsLabel);
        addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (e.getButton() == MouseEvent.BUTTON1) {
                    dots.add(new Point(e.getX(), e.getY()));
                } else if (e.getButton() == MouseEvent.BUTTON3) {
                    if (!dots.isEmpty()) {
                        dots.remove(dots.size() - 1);
                    }
                } else if (e.getButton() == MouseEvent.BUTTON2) {
                    dots.clear();
                }
                dotsLabel.setText(dots.size() + " dot(s)");
            }
        });
    }

    public int dotCount() {
        return dots.size();
    }

    public String lastDot() {
        if (dots.isEmpty()) {
            return "none";
        }
        Point last = dots.get(dots.size() - 1);
        return last.x + "," + last.y;
    }
}
